        fix: "gts fix",
        prepare: "npm run compile",
        "system-test": "c8 mocha build/test/system-test --timeout 600000 && pnpm run test-application",
        "samples-test": "cd samples/ && pnpm link ../ && pnpm test && cd ../",
        "browser-test": "cd test/browser-test && pnpm run prefetch && pnpm install && pnpm test",
        "test-application": "cd test/test-application && pnpm run prefetch && pnpm install && pnpm start",
        prelint: "cd samples; pnpm link ../; pnpm install",
